import { mountDashboard, icon, ASSETS, money, percentage, escapeHTML } from './dashboard.mjs';
export const TRADE_MARKETS=ASSETS.filter(a=>['BTC','ETH','BNB','SOL','XRP'].includes(a.symbol));
export function orderPreview(price,amount){const p=Number(price),a=Number(amount);if(!Number.isFinite(p)||!Number.isFinite(a)||p<=0||a<=0)return {total:0,fee:0};const total=p*a;return Number.isFinite(total)?{total,fee:total*.001}:{total:0,fee:0};}
export function sampleCandles(symbol,timeframe){let seed=[...symbol+timeframe].reduce((a,c)=>a+c.charCodeAt(0),0),last=52;return Array.from({length:56},(_,i)=>{seed=(seed*1664525+1013904223)>>>0;const open=last,close=Math.max(12,Math.min(87,open+(seed%19)-8));last=close;return {open,close,high:Math.min(95,Math.max(open,close)+3+seed%6),low:Math.max(5,Math.min(open,close)-3-seed%5)};});}
export function priceChart(asset,timeframe,type){const candles=sampleCandles(asset.symbol,timeframe),points=candles.map((c,i)=>(18+i*10)+','+(280-c.close*2.4)).join(' ');const grid=[40,100,160,220,280].map((y,i)=>'<line x1="0" x2="580" y1="'+y+'" y2="'+y+'" stroke="#202b25"/><text x="590" y="'+(y+4)+'" fill="#82988b" font-size="10">'+money(asset.price*(1.04-i*.02))+'</text>').join('');const shapes=type==='Candle'?candles.map((c,i)=>{const x=18+i*10,color=c.close>=c.open?'#00d987':'#f24f65';return '<line x1="'+x+'" x2="'+x+'" y1="'+(280-c.high*2.4)+'" y2="'+(280-c.low*2.4)+'" stroke="'+color+'"/><rect x="'+(x-3)+'" y="'+(280-Math.max(c.open,c.close)*2.4)+'" width="6" height="'+Math.max(2,Math.abs(c.close-c.open)*2.4)+'" fill="'+color+'"/>';}).join(''):(type==='Area'?'<polygon points="18,300 '+points+' 568,300" fill="url(#trade-area)"/>':'')+'<polyline points="'+points+'" fill="none" stroke="#00ed87" stroke-width="2"/>';return '<svg class="trade-chart-svg" viewBox="0 0 690 330" role="img" aria-label="Sample '+asset.symbol+' '+timeframe+' '+type.toLowerCase()+' chart"><defs><linearGradient id="trade-area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#00ed87" stop-opacity=".3"/><stop offset="1" stop-color="#00ed87" stop-opacity="0"/></linearGradient></defs>'+grid+shapes+'<text x="18" y="322" fill="#82988b" font-size="10">08:00</text><text x="180" y="322" fill="#82988b" font-size="10">12:00</text><text x="360" y="322" fill="#82988b" font-size="10">16:00</text><text x="530" y="322" fill="#82988b" font-size="10">20:00</text></svg>';}
function marketRows(query=''){return TRADE_MARKETS.filter(a=>(a.symbol+' '+a.name).toLowerCase().includes(query.toLowerCase().trim())).map(a=>'<button class="trade-market-row" data-pair="'+a.symbol+'"><span><img src="/assets/'+a.icon+'@2x.png" alt=""><span><strong>'+a.symbol+'</strong><small>USDT</small></span></span><span>'+money(a.price)+'</span><span class="'+(a.change>=0?'positive':'negative')+'">'+percentage(a.change)+'</span></button>').join('')||'<p class="trade-muted trade-no-results">No matching markets</p>';}
export function tradeHTML(){return '<div class="trade-workspace"><div class="trade-demo">'+icon('shield')+' Trading preview · Sample market data · Order execution is not connected</div><div class="trade-grid"><aside class="trade-panel trade-markets"><h2>Markets</h2><label class="trade-market-search">'+icon('search')+'<input id="trade-market-search" type="search" placeholder="Search pairs..." aria-label="Search trading pairs"></label><div class="trade-market-labels"><span>Pair</span><span>Price</span><span>24h</span></div><div id="trade-market-rows">'+marketRows()+'</div></aside><section class="trade-panel trade-chart-panel" aria-label="Price chart"><div id="trade-market-heading"></div><div class="trade-chart-toolbar"><div class="trade-segments" aria-label="Chart timeframe">'+['1H','4H','1D','1W'].map(t=>'<button data-timeframe="'+t+'" aria-pressed="'+(t==='1H')+'">'+t+'</button>').join('')+'</div><div class="trade-segments" aria-label="Chart style">'+['Candle','Line','Area'].map(t=>'<button data-chart-type="'+t+'" aria-pressed="'+(t==='Candle')+'">'+t+'</button>').join('')+'</div></div><div id="trade-price-chart"></div><div class="trade-chart-caption">Illustrative price history, not live market data</div></section><section class="trade-panel trade-book" aria-labelledby="order-book-title"><div class="trade-panel-title"><h2 id="order-book-title">Order Book</h2><div class="trade-segments">'+['Both','Bids','Asks'].map(t=>'<button data-book="'+t+'" aria-pressed="'+(t==='Both')+'">'+t+'</button>').join('')+'</div></div><div class="trade-book-head"><span>Price</span><span>Amount</span><span>Total</span></div><div id="trade-book-rows"></div><div class="trade-recent"><h2>Recent Trades</h2><div class="trade-book-head"><span>Price</span><span>Amount</span><span>Time</span></div><div id="trade-recent-rows"></div></div></section><section class="trade-panel trade-order" aria-label="Order preview"><div class="trade-side-tabs"><button data-side="Buy" aria-pressed="true">Buy</button><button data-side="Sell" aria-pressed="false">Sell</button></div><div class="trade-segments trade-order-types"><button data-order-type="Limit" aria-pressed="true">Limit</button><button data-order-type="Market" aria-pressed="false">Market</button></div><form id="trade-order-form"><label for="trade-order-price">Price (USDT)</label><input id="trade-order-price" type="number" min="0.000001" step="any" required><label for="trade-order-amount" id="trade-amount-label">Amount (BTC)</label><input id="trade-order-amount" type="number" min="0" step="any" value="0.00" required><input id="trade-allocation" type="range" min="0" max="100" value="0" aria-label="Balance allocation"><div class="trade-allocation-labels">'+[25,50,75,100].map(n=>'<button type="button" data-allocation="'+n+'">'+n+'%</button>').join('')+'</div><label for="trade-order-total">Total (USDT)</label><input id="trade-order-total" value="0.00" readonly><dl class="trade-order-summary"><div><dt>Fee (0.1%, sample)</dt><dd id="trade-order-fee">$0.0000</dd></div><div><dt id="trade-available-label">Available (USDT)</dt><dd id="trade-available">0 USDT</dd></div></dl><button type="submit" id="trade-submit" class="deposit-continue">Buy BTC</button><p id="trade-order-feedback" role="status" class="transfer-placeholder-note" hidden></p><p class="trade-order-disclaimer">Preview only. No orders or balance changes are created.</p></form></section><section class="trade-panel trade-orders" aria-label="Trading activity"><div class="trade-activity-tabs">'+['Orders','History','Positions'].map(t=>'<button data-activity="'+t+'" aria-pressed="'+(t==='Orders')+'">'+icon(t==='History'?'volume':t==='Positions'?'wallet':'markets')+t+'</button>').join('')+'</div><div class="trade-empty-activity" id="trade-activity-content">'+icon('markets')+'<p>No open orders</p><small>Orders will appear here when trading is connected.</small></div></section></div></div>';}
export function mountTrade(root,options={}){mountDashboard(root,{...options,view:'trade',mainHTML:tradeHTML()});const main=root.querySelector('main');let asset=TRADE_MARKETS.find(a=>a.symbol==='BTC'),timeframe='1H',type='Candle',side='Buy',orderType='Limit',book='Both';const price=main.querySelector('#trade-order-price'),amount=main.querySelector('#trade-order-amount'),feedback=main.querySelector('#trade-order-feedback');
function updateTotals(){const result=orderPreview(price.value,amount.value);main.querySelector('#trade-order-total').value=result.total.toFixed(2);main.querySelector('#trade-order-fee').textContent='$'+result.fee.toFixed(4);feedback.hidden=true;}
function rows(sell){return Array.from({length:8},(_,i)=>{const p=asset.price*(1+(sell?1:-1)*(sell?8-i:i+1)*.0005),qty=.012+(i*37%123)/100;return '<div class="trade-book-row '+(sell?'ask':'bid')+'" style="--depth:'+(18+i*9)+'%"><span>'+p.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+'</span><span>'+qty.toFixed(4)+'</span><span>'+(p*qty).toFixed(2)+'</span></div>';}).join('');}
function renderBook(){main.querySelector('#trade-book-rows').innerHTML=(book!=='Bids'?rows(true):'')+'<div class="trade-book-mid '+(asset.change>=0?'positive':'negative')+'">'+money(asset.price)+' <span>'+percentage(asset.change)+'</span></div>'+(book!=='Asks'?rows(false):'');main.querySelector('#trade-recent-rows').innerHTML=Array.from({length:7},(_,i)=>'<div class="trade-book-row '+(i%3?'bid':'ask')+'"><span>'+(asset.price*(1+(i%3-1)*.0002)).toFixed(2)+'</span><span>'+(0.012+i*.023).toFixed(4)+'</span><span>12:'+String(59-i).padStart(2,'0')+':'+String(55-i*5).padStart(2,'0')+'</span></div>').join('');}
function renderChart(){main.querySelector('#trade-price-chart').innerHTML=priceChart(asset,timeframe,type);}
function updateSide(){main.querySelector('#trade-amount-label').textContent='Amount ('+asset.symbol+')';main.querySelector('#trade-submit').textContent=side+' '+asset.symbol;main.querySelector('#trade-submit').classList.toggle('sell',side==='Sell');main.querySelector('#trade-available-label').textContent='Available ('+(side==='Buy'?'USDT':asset.symbol)+')';main.querySelector('#trade-available').textContent='0 '+(side==='Buy'?'USDT':asset.symbol);feedback.hidden=true;}
function renderMarket(){main.querySelector('#trade-market-heading').innerHTML='<div class="trade-pair-title"><img src="/assets/'+asset.icon+'@2x.png" alt=""><div><h1>'+asset.symbol+'/USDT</h1><span>'+escapeHTML(asset.name)+'</span></div><div class="trade-live-price"><strong class="'+(asset.change>=0?'positive':'negative')+'">'+money(asset.price)+'</strong><span class="'+(asset.change>=0?'positive':'negative')+'">'+percentage(asset.change)+'</span></div></div><dl class="trade-market-stats"><div><dt>24h High</dt><dd>'+money(asset.price*1.025)+'</dd></div><div><dt>24h Low</dt><dd>'+money(asset.price*.975)+'</dd></div><div><dt>24h Volume</dt><dd>$'+asset.volume+'</dd></div></dl>';price.value=asset.price;amount.value='0.00';main.querySelector('#trade-allocation').value=0;main.querySelectorAll('[data-pair]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.pair===asset.symbol));updateSide();updateTotals();renderChart();renderBook();}
function pressed(selector,target){main.querySelectorAll(selector).forEach(b=>b.setAttribute('aria-pressed',b===target));}
main.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pair){asset=TRADE_MARKETS.find(a=>a.symbol===b.dataset.pair);renderMarket();}if(b.dataset.timeframe){timeframe=b.dataset.timeframe;pressed('[data-timeframe]',b);renderChart();}if(b.dataset.chartType){type=b.dataset.chartType;pressed('[data-chart-type]',b);renderChart();}if(b.dataset.book){book=b.dataset.book;pressed('[data-book]',b);renderBook();}if(b.dataset.side){side=b.dataset.side;pressed('[data-side]',b);updateSide();}if(b.dataset.orderType){orderType=b.dataset.orderType;price.readOnly=orderType==='Market';if(price.readOnly)price.value=asset.price;pressed('[data-order-type]',b);updateTotals();}if(b.dataset.allocation){main.querySelector('#trade-allocation').value=b.dataset.allocation;amount.value='0.00';updateTotals();feedback.hidden=false;feedback.textContent='Available balance is zero. Allocation remains zero in this preview.';}if(b.dataset.activity){pressed('[data-activity]',b);const messages={Orders:['No open orders','Orders will appear here when trading is connected.'],History:['No trade history','Completed trades will appear here.'],Positions:['No open positions','Positions will appear here when trading is connected.']},message=messages[b.dataset.activity];main.querySelector('#trade-activity-content').innerHTML=icon('markets')+'<p>'+message[0]+'</p><small>'+message[1]+'</small>';}};
main.querySelector('#trade-market-search').oninput=e=>{main.querySelector('#trade-market-rows').innerHTML=marketRows(e.target.value);main.querySelectorAll('[data-pair]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.pair===asset.symbol));};price.oninput=updateTotals;amount.oninput=updateTotals;main.querySelector('#trade-allocation').oninput=()=>{amount.value='0.00';updateTotals();};main.querySelector('#trade-order-form').onsubmit=e=>{e.preventDefault();feedback.hidden=false;feedback.textContent=side+' '+asset.symbol+' '+orderType.toLowerCase()+' order preview only. Nothing was submitted. No funds were moved.';};renderMarket();window.scrollTo(0,0);}
